with valid_products as (select *, least(cost, stock_qty) as least_cost_stock_qty from products where launch_date <= '2023-10-01'), products_stats as (select category, sort_array(collect_set(category)) as category_list, avg(least_cost_stock_qty) as avg_least_cost_stock_qty from valid_products group by category) select category, category_list, avg_least_cost_stock_qty from products_stats order by avg_least_cost_stock_qty desc, category;
